var n=`0954-gyudon`;var t=`world-0954`;var o=`JP`;var s=`east-asia`;var a=4;var r=49;var l={en:`Gyudon`,ua:`Ґюдон`};var d={en:`Gyudon is a Japan dish made with jasmine rice, beef sirloin, yellow onion, light soy sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ґюдон, страва кухні країни Японія. Основні складники: рис жасмин, яловичий сирлойн, жовта цибуля, світлий соєвий соус. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,410,`g`],[`water`,780,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`beef-sirloin`,560,`g`],[`yellow-onion`,220,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 11 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 11 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:11,i:[[`dashi-stock`,360,`ml`],[`mirin`,65,`ml`],[`light-soy-sauce`,65,`ml`],[`white-granulated-sugar`,28,`g`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`pickled-ginger`,55,`g`]]}];var u={slug:n,id:t,country:`JP`,region:s,servings:4,minutes:49,title:l,text:d,steps:g};export{o as country,u as default,t as id,r as minutes,s as region,a as servings,n as slug,g as steps,d as text,l as title};